// Master Unified Gram Panchayats collection
export const TN_LGD_ALL_GRAM_PANCHAYATS = [
  ...TN_LGD_PART1_GRAM_PANCHAYATS,
  ...TN_LGD_PART2_GRAM_PANCHAYATS,
  ...TN_LGD_PART3_GRAM_PANCHAYATS,
  ...TN_LGD_PART4_GRAM_PANCHAYATS
];

// Helper utilities for LGD exploration and resolution
export function getGramPanchayatsByBlock(blockCode) {
  const bCode = Number(blockCode);
  return TN_LGD_ALL_GRAM_PANCHAYATS.filter(gp => gp.parentCode === bCode);
}

export function getGramPanchayatsByDistrict(districtName) {
  if (!districtName || districtName.toLowerCase() === 'all') {
    return TN_LGD_ALL_GRAM_PANCHAYATS;
  }
  const dist = districtName.toLowerCase();
  return TN_LGD_ALL_GRAM_PANCHAYATS.filter(gp => 
    gp.district.toLowerCase() === dist
  );
}

export function searchLgdEntities(query) {
  if (!query || query.trim() === '') return [];
  const q = query.toLowerCase().trim();
  return TN_LGD_ALL_GRAM_PANCHAYATS.filter(gp => 
    gp.name.toLowerCase().includes(q) || 
    gp.code.toString().includes(q) ||
    gp.block.toLowerCase().includes(q) ||
    gp.district.toLowerCase().includes(q)
  );
}

export function getLgdHierarchy(panchayatCode) {
  const pCode = Number(panchayatCode);
  const gp = TN_LGD_ALL_GRAM_PANCHAYATS.find(p => p.code === pCode);
  if (!gp) return null;
  const block = TN_LGD_BLOCKS_MAP[gp.parentCode] || { name: gp.block, district: gp.district };
  const zila = TN_LGD_ZILA_PANCHAYATS.find(z => z.name.toLowerCase() === gp.district.toLowerCase()) || { name: gp.district };
  return {
    gramPanchayat: gp,
    block: { code: gp.parentCode, name: block.name },
    district: { name: gp.district, code: block.parentZilaCode || zila.code },
    state: { code: 33, name: 'Tamil Nadu' }
  };
}

export const TN_LGD_STATS = {
  stateCode: 33,
  stateName: 'Tamil Nadu',
  zilaPanchayatsCount: TN_LGD_ZILA_PANCHAYATS.length,
  blocksCount: Object.keys(TN_LGD_BLOCKS_MAP).length,
  part1GramPanchayatsCount: TN_LGD_PART1_GRAM_PANCHAYATS.length,
  part2GramPanchayatsCount: TN_LGD_PART2_GRAM_PANCHAYATS.length,
  part3GramPanchayatsCount: TN_LGD_PART3_GRAM_PANCHAYATS.length,
  part4GramPanchayatsCount: TN_LGD_PART4_GRAM_PANCHAYATS.length,
  totalGramPanchayatsCount: TN_LGD_ALL_GRAM_PANCHAYATS.length
};
